css:
.lusitania-sim-container {
    padding: 20px;
    background: linear-gradient(165deg, #141a24 0%, #1b2430 55%, #202b3a 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #d7dee8;
}

.lusitania-sim-header {
    background: linear-gradient(135deg, #202d3f 0%, #2c3e57 55%, #344a68 100%);
    color: #f2f5fa;
    padding: 32px 30px;
    border-radius: 16px;
    margin-bottom: 22px;
    box-shadow: 0 14px 34px rgba(0,0,0,0.45);
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(224,168,46,0.28);
}

.lusitania-sim-header::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(224,168,46,0.12) 0%, transparent 60%);
    pointer-events: none;
}

.lusitania-sim-header-icon {
    font-size: 2.6rem;
    margin-bottom: 8px;
}

.lusitania-sim-header h1 {
    font-size: 1.95rem;
    font-weight: 800;
    margin-bottom: 6px;
    letter-spacing: 0.4px;
    font-family: 'Segoe UI', Georgia, serif;
}

.lusitania-sim-header p {
    font-size: 1rem;
    opacity: 0.9;
    margin: 0 0 14px 0;
    letter-spacing: 0.5px;
}

.lusitania-sim-clock {
    display: inline-block;
    background: rgba(0,0,0,0.34);
    border: 1px solid rgba(224,168,46,0.5);
    border-radius: 999px;
    padding: 6px 18px;
    font-size: 0.92rem;
    font-weight: 600;
    letter-spacing: 0.4px;
}

.lusitania-sim-clock #deadlineDisplay {
    color: #f0c054;
    font-weight: 800;
    margin: 0 4px;
}

.lusitania-sim-period-counter {
    text-align: center;
    font-size: 1.05rem;
    color: #9fb0c3;
    margin-bottom: 22px;
    font-weight: 600;
}

.lusitania-sim-period-counter span {
    margin: 0 3px;
}

.lusitania-sim-period-counter #currentDay,
.lusitania-sim-period-counter #maxPeriods {
    color: #f0c054;
    font-weight: 800;
}

.lusitania-sim-round-name {
    display: inline-block;
    margin-left: 10px;
    padding: 3px 14px;
    background: rgba(224,168,46,0.12);
    border: 1px solid rgba(224,168,46,0.4);
    border-radius: 999px;
    color: #f0c054;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

/* ---- KPI cards ---- */
.lusitania-sim-kpi-section {
    margin-bottom: 22px;
}

.lusitania-sim-kpi-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 16px;
}

.lusitania-sim-kpi-cards-secondary {
    grid-template-columns: repeat(3, 1fr);
    margin-bottom: 0;
}

.lusitania-sim-kpi-card {
    background: linear-gradient(160deg, #212d3d 0%, #1c2735 100%);
    border: 1px solid rgba(159,176,195,0.14);
    border-radius: 14px;
    padding: 18px 18px 20px;
    box-shadow: 0 8px 22px rgba(0,0,0,0.35);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.lusitania-sim-kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 12px 30px rgba(0,0,0,0.5);
}

.lusitania-kpi-hero {
    border: 1px solid rgba(224,168,46,0.55);
    background: linear-gradient(160deg, #2a2a1f 0%, #242f3f 100%);
}

.lusitania-kpi-risk {
    border: 1px solid rgba(217,100,90,0.4);
}

.lusitania-sim-kpi-label {
    font-size: 0.8rem;
    color: #8fa0b4;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px;
    font-weight: 700;
}

.lusitania-sim-kpi-value {
    font-size: 2.6rem;
    font-weight: 800;
    color: #eef3f9;
    line-height: 1.05;
}

.lusitania-kpi-hero .lusitania-sim-kpi-value {
    color: #f0c054;
}

.lusitania-kpi-risk .lusitania-sim-kpi-value {
    color: #e98a82;
}

.lusitania-kpi-small .lusitania-sim-kpi-value {
    font-size: 1.4rem;
    color: #cdd7e3;
}

.lusitania-sim-kpi-sub {
    font-size: 0.74rem;
    color: #7d8da0;
    margin-top: 8px;
    line-height: 1.3;
}

.lusitania-sim-kpi-bar-bg {
    height: 8px;
    background: rgba(159,176,195,0.14);
    border-radius: 6px;
    margin-top: 12px;
    overflow: hidden;
}

.lusitania-sim-kpi-bar-fill {
    height: 100%;
    border-radius: 6px;
    transition: width 0.5s ease;
}

.lusitania-trust-fill { background: linear-gradient(90deg, #c98f24, #f0c054); }
.lusitania-adoption-fill { background: linear-gradient(90deg, #2c8175, #4fc2b1); }
.lusitania-ethics-fill { background: linear-gradient(90deg, #4f6db0, #84a4dd); }
.lusitania-risk-fill { background: linear-gradient(90deg, #b9463c, #e98a82); }

/* ---- Briefing ---- */
.lusitania-sim-briefing {
    background: linear-gradient(160deg, #1f2a39 0%, #1a2330 100%);
    border: 1px solid rgba(159,176,195,0.14);
    border-left: 4px solid #e0a82e;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 8px 22px rgba(0,0,0,0.35);
}

.lusitania-sim-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #f0c054;
}

.lusitania-sim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.65;
    color: #c4cedb;
}

.lusitania-sim-briefing-text strong {
    color: #f2f5fa;
}

.lusitania-sim-briefing-text em {
    color: #84a4dd;
    font-style: italic;
}

.lusitania-sim-event-alert {
    margin-top: 16px;
    padding: 14px 16px;
    background: rgba(217,100,90,0.12);
    border: 1px solid rgba(217,100,90,0.45);
    border-radius: 10px;
    color: #f0a59d;
    font-size: 0.92rem;
    line-height: 1.55;
}

.lusitania-sim-event-alert strong {
    color: #ffd7d2;
}

/* ---- Controls ---- */
.lusitania-sim-controls {
    background: linear-gradient(160deg, #1f2a39 0%, #1a2330 100%);
    border: 1px solid rgba(159,176,195,0.14);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 22px;
    box-shadow: 0 8px 22px rgba(0,0,0,0.35);
}

.lusitania-sim-controls h3 {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: #eef3f9;
}

.lusitania-sim-decisions-note {
    font-size: 0.86rem;
    color: #9fb0c3;
    margin-bottom: 18px;
    font-style: italic;
}

.lusitania-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px 22px;
}

.lusitania-sim-input-group {
    display: flex;
    flex-direction: column;
}

.lusitania-sim-input-group label {
    font-size: 0.9rem;
    font-weight: 600;
    color: #cdd7e3;
    margin-bottom: 7px;
}

.lusitania-sim-container .form-control {
    background-color: #131b26;
    color: #e8eef5;
    border: 1px solid rgba(159,176,195,0.28);
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
}

.lusitania-sim-container .form-control:focus {
    border-color: #e0a82e;
    box-shadow: 0 0 0 3px rgba(224,168,46,0.22);
    background-color: #131b26;
    color: #e8eef5;
    outline: none;
}

.lusitania-sim-container select.form-control {
    background-color: #131b26;
    color: #e8eef5;
}

.lusitania-sim-container select.form-control option {
    background-color: #131b26;
    color: #e8eef5;
}

.lusitania-sim-hint {
    font-size: 0.76rem;
    color: #7d8da0;
    margin-top: 6px;
    line-height: 1.35;
}

.lusitania-sim-spend-meter {
    margin-top: 20px;
    padding: 14px 16px;
    background: rgba(224,168,46,0.06);
    border: 1px solid rgba(224,168,46,0.2);
    border-radius: 10px;
}

.lusitania-sim-spend-row {
    display: flex;
    align-items: baseline;
    gap: 8px;
    font-size: 0.9rem;
    font-weight: 600;
    color: #cdd7e3;
    margin-bottom: 8px;
    flex-wrap: wrap;
}

.lusitania-sim-spend-row #spendDisplayMeter {
    font-size: 1.15rem;
    font-weight: 800;
    color: #f0c054;
}

.lusitania-sim-spend-bar-bg {
    height: 10px;
    background: rgba(159,176,195,0.16);
    border-radius: 6px;
    overflow: hidden;
}

.lusitania-sim-spend-bar-fill {
    height: 100%;
    border-radius: 6px;
    background: linear-gradient(90deg, #2c8175, #4fc2b1);
    transition: width 0.4s ease, background 0.4s ease;
}

.lusitania-sim-spend-bar-fill.lusitania-over {
    background: linear-gradient(90deg, #b9463c, #e98a82);
}

.lusitania-sim-btn-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 22px;
    flex-wrap: wrap;
}

.lusitania-sim-container .btn-primary {
    background: linear-gradient(135deg, #c98f24 0%, #e0a82e 100%);
    border: none;
    font-weight: 700;
    letter-spacing: 0.4px;
    padding: 12px 30px;
    border-radius: 10px;
    box-shadow: 0 6px 16px rgba(224,168,46,0.32);
    color: #1a1305;
}

.lusitania-sim-container .btn-primary:hover {
    background: linear-gradient(135deg, #d89a2b 0%, #f0c054 100%);
    color: #160f02;
}

.lusitania-sim-container .btn-outline-secondary {
    color: #aebccd;
    border-color: rgba(159,176,195,0.4);
    border-radius: 10px;
    background: transparent;
}

.lusitania-sim-container .btn-outline-secondary:hover {
    background: rgba(159,176,195,0.1);
    color: #eef3f9;
}

/* ---- Charts ---- */
.lusitania-sim-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.lusitania-sim-chart-box {
    background: linear-gradient(160deg, #1f2a39 0%, #1a2330 100%);
    border: 1px solid rgba(159,176,195,0.14);
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 8px 22px rgba(0,0,0,0.35);
    min-height: 320px;
}

/* ---- History ---- */
.lusitania-sim-history {
    background: linear-gradient(160deg, #1f2a39 0%, #1a2330 100%);
    border: 1px solid rgba(159,176,195,0.14);
    border-radius: 14px;
    padding: 22px 24px;
    box-shadow: 0 8px 22px rgba(0,0,0,0.35);
}

.lusitania-sim-history h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #eef3f9;
}

.lusitania-sim-history table {
    color: #c4cedb;
    margin-bottom: 0;
}

.lusitania-sim-history .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(159,176,195,0.05);
}

.lusitania-sim-history th {
    color: #8fa0b4;
    border-color: rgba(159,176,195,0.2);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.lusitania-sim-history td {
    border-color: rgba(159,176,195,0.12);
    font-size: 0.88rem;
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
    .lusitania-sim-container {
        padding: 12px;
    }
    .lusitania-sim-header h1 {
        font-size: 1.45rem;
    }
    .lusitania-sim-kpi-cards,
    .lusitania-sim-kpi-cards-secondary {
        grid-template-columns: 1fr;
    }
    .lusitania-sim-input-grid {
        grid-template-columns: 1fr;
    }
    .lusitania-sim-charts {
        grid-template-columns: 1fr;
    }
    .lusitania-sim-kpi-value {
        font-size: 2.1rem;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.et-completion { padding: 8px 4px 4px; }
.et-cm-head { text-align: center; margin-bottom: 16px; }
.et-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #6ea8ff; }
.et-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #9fb0c3; }
.et-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #e8eef5; }
.et-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.et-cm-yes { background: rgba(74,200,140,0.16); color: #4ac88c; border: 1px solid rgba(74,200,140,0.45); }
.et-cm-no { background: rgba(255,120,110,0.14); color: #ff8c82; border: 1px solid rgba(255,120,110,0.5); }
.et-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.et-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(110,168,255,0.08); border: 1px solid rgba(110,168,255,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.et-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #6ea8ff; }
.et-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #9fb0c3; text-transform: uppercase; letter-spacing: 0.03em; }
.et-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #e8eef5; }
.et-cm-insights { margin: 0; padding-left: 20px; }
.et-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #c4cedb; }

