                    briefingEs: `🏛️ <strong>30 de septiembre de 2026 — llega la fecha límite y se resuelven los resultados.</strong> El movimiento del índice de confianza, la tasa de adopción, la ética percibida y el riesgo de rotación cristalizan a partir de tus decisiones. Entonces aparece un evento en vivo: un <strong>post interno viral que acusa al liderazgo de “volver a hacerlo”</strong> alcanza 800 visitas, y llega el resultado del preaviso de huelga.<br><br>Elige tu <strong>respuesta en tiempo real</strong>. <em>Mantén la línea</em> y señala el gesto reparador que ya tienes en el banco. <em>Cede terreno</em> al sindicato para comprar paz. <em>Acelera</em> para llegar a la fecha cueste lo que cueste. O haz <em>un gesto reparador adicional</em> ahora, bajo presión.<br><br>La lección que enseña el post: la confianza es un activo que se ahorra <strong>antes</strong> de la crisis y se gasta bajo presión — el silencio se lee como culpa, una negación defensiva se lee como el equipo anterior, e improvisar una reparación ahora es mucho más débil que señalar una que ya hiciste. Defiende el despliegue ante el facilitador que hace de consejo (que quiere velocidad) y de comité de empresa (que quiere protección) — y da una cuenta honesta de si esta vez mantuviste la palabra.`,
                    eventEn: `🎙️ <strong>“They're doing it again.”</strong> An internal post accusing leadership of repeating the profit-share betrayal hits 800 views in an hour, and the union announces the strike ballot result. If you banked a credible repair move, you have something to point to. If not, that silence is the lesson.`,
                    eventEs: `🎙️ <strong>“Lo están volviendo a hacer.”</strong> Un post interno que acusa al liderazgo de repetir la traición del plan de beneficios alcanza 800 visitas en una hora, y el sindicato anuncia el resultado del preaviso de huelga. Si tienes un gesto reparador creíble en el banco, tienes algo que señalar. Si no, ese silencio es la lección.`
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trustIndex: 38,        // hero KPI, 0-100, benchmark ~65
                    adoption: 20,          // % of teams switched to the new system on time
                    ethicality: 50,        // perceived ethicality of leadership, 0-100
                    turnoverRisk: 55,      // risk of losing the staff you must keep, 0-100 (LOWER is better)
                    repairSpent: 0,        // cumulative EUR thousands committed to repair moves
                    strikeRisk: 70,        // 0-100 likelihood of a walkout at peak season (lower better)
                    financialImpact: 0,    // cumulative EUR M (client volume kept/lost, attrition cost)
                    diagnosedRight: false, // did the team identify integrity as the damaged component
                    profitShareNamed: false, // did the team ever acknowledge the cancelled profit-share
                    overPromised: false,   // did the team ever over-promise "no job losses"
                    outcome: 'inprogress', // 'inprogress' | 'landed' | 'detonated'
                    trustHistory: [],
                    adoptionHistory: [],
                    ethicsHistory: [],
                    riskHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    component: 'integrity',
                    diagnosisDepth: 50,
                    framing: 'full_transparency',
                    acknowledge: 'yes',
                    promise: 'honest',
                    repair: 'binding_guarantee',
                    repairSpend: 2600,
                    crisisResponse: 'hold'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var componentEl = document.getElementById('componentInput');
            var depthEl = document.getElementById('diagnosisDepthInput');
            var framingEl = document.getElementById('framingInput');
            var ackEl = document.getElementById('acknowledgeInput');
            var promiseEl = document.getElementById('promiseInput');
            var repairEl = document.getElementById('repairInput');
            var spendEl = document.getElementById('repairSpendInput');
            var crisisEl = document.getElementById('crisisResponseInput');

            if (componentEl) decisions.component = componentEl.value;
            if (depthEl) decisions.diagnosisDepth = parseInt(depthEl.value, 10);
            if (framingEl) decisions.framing = framingEl.value;
            if (ackEl) decisions.acknowledge = ackEl.value;
            if (promiseEl) decisions.promise = promiseEl.value;
            if (repairEl) decisions.repair = repairEl.value;
            if (spendEl) decisions.repairSpend = parseInt(spendEl.value, 10);
            if (crisisEl) decisions.crisisResponse = crisisEl.value;

            if (['ability', 'benevolence', 'integrity'].indexOf(decisions.component) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('component_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.diagnosisDepth) || decisions.diagnosisDepth < 0 || decisions.diagnosisDepth > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('depth_warning'), 'warning');
                return false;
            }
            if (!this.FRAMES[decisions.framing]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('framing_warning'), 'warning');
                return false;
            }
            if (['yes', 'no'].indexOf(decisions.acknowledge) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('acknowledge_warning'), 'warning');
                return false;
            }
            if (['honest', 'overpromise'].indexOf(decisions.promise) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('promise_warning'), 'warning');
                return false;
            }
            if (!this.REPAIRS[decisions.repair]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('repair_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.repairSpend) || decisions.repairSpend < 0 || decisions.repairSpend > this.EBIT_CAP_K) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('spend_warning'), 'warning');
                return false;
            }
            if (['hold', 'concede', 'accelerate', 'further_repair'].indexOf(decisions.crisisResponse) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('crisis_warning'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var frame = this.FRAMES[d.framing];
            var repair = this.REPAIRS[d.repair];

            // ---- Round 1: diagnosis governs how well every later move lands ----
            var diagnosedRight = (d.component === this.TRUE_DAMAGED_COMPONENT);
            if (diagnosedRight) ds.diagnosedRight = true;
            // Depth: jumping to action with a shallow read caps later credibility gains.
            var depthFactor = 0.5 + (d.diagnosisDepth / 100) * 0.5; // 0.5 .. 1.0
            // Misdiagnosis aimed at ability/benevolence reaches for the wrong repair: it
            // dampens how much an integrity-repair move can restore.
            var diagnosisAlign = diagnosedRight ? 1.0 : 0.6;

            // ---- Round 2: framing, acknowledgement, promise honesty ----
            // Low-trust inversion: gains-first is read as spin and erodes trust/ethicality.
            var trustDelta = frame.trustBuild;
            var ethicsDelta = frame.ethicality;
            var adoptionDelta = frame.adoptionPull;

            // Acknowledging the cancelled profit-share is the precondition for being believed.
            if (d.acknowledge === 'yes') {
                ds.profitShareNamed = true;
                trustDelta += 6;
                ethicsDelta += 6;
            } else {
                // An unaddressed violation festers: it caps trust gains and bleeds ethicality.
                trustDelta -= 8;
                ethicsDelta -= 8;
            }

            // Over-promising "no job losses" buys short-term calm but writes a cheque you can't cash.
            if (d.promise === 'overpromise') {
                ds.overPromised = true;
                // Small immediate adoption bump...
                adoptionDelta += 6;
                // ...but it widens the say-do gap: ethicality falls and a latent second-broken-
                // promise penalty is armed, detonating at resolution (Round 4).
                ethicsDelta -= 10;
            }

            // Union engagement (co-created framing) is the procedural-justice lever that cools
            // the strike risk; ignoring the union keeps the ballot live.
            if (frame.unionEngaged) {
                ds.strikeRisk = Math.max(0, ds.strikeRisk - 22);
                adoptionDelta += 4;
            } else if (period >= 2) {
                // Top-down: the strike ballot stays hot and creeps up at peak season.
                ds.strikeRisk = Math.min(100, ds.strikeRisk + 6);
            }

            // ---- Round 3+: the trust-repair move ----
            // Integrity-based trust is repaired by self-constraining ACTION, scaled by how
            // well the move is actually funded and by diagnosis alignment.
            var repairActive = (period >= 3);
            if (repairActive) {
                ds.repairSpent = d.repairSpend;
                // Funding adequacy: the move only lands if you pay enough to make it real.
                // words_only has costK 0 -> fundFactor 1 but its integrity payoff is ~0 anyway.
                var fundFactor = repair.costK > 0 ? Math.min(1, d.repairSpend / repair.costK) : 1;
                var repairTrust = repair.integrity * fundFactor * diagnosisAlign * depthFactor;
                trustDelta += repairTrust;
                ethicsDelta += repair.integrity * 0.35 * fundFactor;
                adoptionDelta += repair.adoption * fundFactor;
                ds.turnoverRisk = Math.max(0, ds.turnoverRisk - repair.riskCut * fundFactor);

                // Over-spending beyond what the 6% EBIT can carry reads as reckless, not generous.
                if (d.repairSpend > this.EBIT_CAP_K * 0.4) {
                    ethicsDelta -= 5;
                    ds.financialImpact = Math.round((ds.financialImpact - 1.5) * 10) / 10;
                }
                // Words-only at a trust index this low: the lesson lands hard.
                if (d.repair === 'words_only') {
                    trustDelta -= 4;
                    ds.turnoverRisk = Math.min(100, ds.turnoverRisk + 6);
                }
            }

            // Apply the per-round deltas, gated by depth so a shallow diagnosis caps upside.
            var gatedTrust = trustDelta > 0 ? trustDelta * depthFactor : trustDelta;
            ds.trustIndex = Math.max(0, Math.min(100, Math.round(ds.trustIndex + gatedTrust)));
            ds.ethicality = Math.max(0, Math.min(100, Math.round(ds.ethicality + ethicsDelta)));
            ds.adoption = Math.max(0, Math.min(100, Math.round(ds.adoption + adoptionDelta)));

            // ---- Round 4: crisis response + final resolution ----
            if (period === 4) {
                // The viral post: a response is only credible if a repair move was banked earlier.
                var bankedRepair = ds.repairSpent > 0 && d.repair !== 'words_only';
                if (d.crisisResponse === 'hold') {
                    if (bankedRepair) {
                        ds.trustIndex = Math.min(100, ds.trustIndex + 6);
                        ds.ethicality = Math.min(100, ds.ethicality + 4);
                    } else {
                        // Holding with nothing to point to: silence reads as guilt.
                        ds.trustIndex = Math.max(0, ds.trustIndex - 8);
                        ds.ethicality = Math.max(0, ds.ethicality - 6);
                    }
                } else if (d.crisisResponse === 'concede') {
                    // Conceding cools the strike and lifts adoption, but a board reading of caving
                    // costs some client confidence (financial) and a little credibility.
                    ds.strikeRisk = Math.max(0, ds.strikeRisk - 25);
                    ds.adoption = Math.min(100, ds.adoption + 8);
                    ds.trustIndex = Math.max(0, ds.trustIndex - 3);
                    ds.financialImpact = Math.round((ds.financialImpact - 2) * 10) / 10;
                } else if (d.crisisResponse === 'accelerate') {
                    // Speed without trust: the strike detonates the SLAs you raced to protect.
                    ds.strikeRisk = Math.min(100, ds.strikeRisk + 20);
                    ds.adoption = Math.max(0, ds.adoption - 10);
                    ds.trustIndex = Math.max(0, ds.trustIndex - 6);
                } else if (d.crisisResponse === 'further_repair') {
                    // Improvised under pressure: weaker than a banked move, and the spend stings.
                    ds.trustIndex = Math.min(100, ds.trustIndex + 4);
                    ds.ethicality = Math.min(100, ds.ethicality + 3);
                    ds.turnoverRisk = Math.max(0, ds.turnoverRisk - 5);
                    ds.financialImpact = Math.round((ds.financialImpact - 1) * 10) / 10;
                }

                // SECOND BROKEN PROMISE: over-promised AND ended below a credibility floor ->
                // trust hits the floor and turnover among the staff you must keep spikes.
                if (ds.overPromised && ds.trustIndex < 55) {
                    ds.trustIndex = Math.max(0, Math.round(ds.trustIndex * 0.55));
                    ds.turnoverRisk = Math.min(100, ds.turnoverRisk + 22);
                    ds.ethicality = Math.max(0, ds.ethicality - 10);
                }

                // Never naming the profit-share leaves the violation poisoning the result.
                if (!ds.profitShareNamed) {
                    ds.trustIndex = Math.max(0, ds.trustIndex - 6);
                    ds.ethicality = Math.max(0, ds.ethicality - 6);
                }

                // Strike resolution: a live ballot above the danger line breaks SLAs at peak season.
                if (ds.strikeRisk >= 55) {
                    ds.adoption = Math.max(0, ds.adoption - 18);
                    ds.financialImpact = Math.round((ds.financialImpact - 12) * 10) / 10; // SLA breach, client volume cut
                }

                // Deadline / client-volume resolution (40% of revenue rides on adoption by 30 Sep).
                if (ds.adoption >= 70 && ds.strikeRisk < 55) {
                    ds.financialImpact = Math.round((ds.financialImpact + 14) * 10) / 10; // clients retained, automation case delivered
                } else if (ds.adoption < 50) {
                    ds.financialImpact = Math.round((ds.financialImpact - 10) * 10) / 10; // clients cut volume
                }

                // Turnover cost: every point of turnover risk above 50 erodes the operation.
                if (ds.turnoverRisk > 50) {
                    var attrition = Math.round((ds.turnoverRisk - 50) / 10 * 10) / 10;
                    ds.financialImpact = Math.round((ds.financialImpact - attrition) * 10) / 10;
                }

                // Outcome: the change lands only if trust recovered, adoption held, the workforce
                // is staying, leadership read as ethical, and no strike broke the SLAs.
                var landed = ds.trustIndex >= 55 && ds.adoption >= 70 && ds.ethicality >= 55 &&
                             ds.turnoverRisk <= 45 && ds.strikeRisk < 55;
                ds.outcome = landed ? 'landed' : 'detonated';
            } else {
                ds.outcome = 'inprogress';
            }

            // ---- History ----
            ds.trustHistory.push(ds.trustIndex);
            ds.adoptionHistory.push(ds.adoption);
            ds.ethicsHistory.push(ds.ethicality);
            ds.riskHistory.push(ds.turnoverRisk);

            this._updateBars(ds);

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: period,
                component: d.component,
                diagnosisDepth: d.diagnosisDepth,
                framing: d.framing,
                acknowledge: d.acknowledge,
                promise: d.promise,
                repair: d.repair,
                repairSpend: d.repairSpend,
                crisisResponse: d.crisisResponse,
                diagnosedRight: ds.diagnosedRight,
                profitShareNamed: ds.profitShareNamed,
                overPromised: ds.overPromised,
                trustIndex: ds.trustIndex,
                adoption: ds.adoption,
                ethicality: ds.ethicality,
                turnoverRisk: ds.turnoverRisk,
                strikeRisk: ds.strikeRisk,
                repairSpent: ds.repairSpent,
                financialImpact: ds.financialImpact,
                outcome: ds.outcome
            };
        }

        _updateBars(ds) {
            var trust = document.getElementById('trustBar');
            var adopt = document.getElementById('adoptionBar');
            var ethics = document.getElementById('ethicsBar');
            var risk = document.getElementById('riskBar');
            if (trust) trust.style.width = ds.trustIndex + '%';
            if (adopt) adopt.style.width = ds.adoption + '%';
            if (ethics) ethics.style.width = ds.ethicality + '%';
            // Turnover risk bar: lower is better, so fill represents the risk level.
            if (risk) risk.style.width = ds.turnoverRisk + '%';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                lang = (window.mySimulation && window.mySimulation.lang) ? window.mySimulation.lang : 'en';
            } catch (e) { lang = 'en'; }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefingEn;
            }

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) {
                nameEl.textContent = lang === 'es' ? round.nameEs : round.nameEn;
            }

            var noteEl = document.getElementById('liveLeversNote');
            if (noteEl) {
                var noteKey = 'levers_note_r' + (idx + 1);
                try { noteEl.textContent = window.mySimulation.t(noteKey); } catch (e) {}
            }

            var eventEl = document.getElementById('eventAlert');
            if (eventEl) {
                var eventText = lang === 'es' ? round.eventEs : round.eventEn;
                if (eventText) {
                    eventEl.innerHTML = eventText;
                    eventEl.style.display = 'block';
                } else {
                    eventEl.style.display = 'none';
                }
            }

            this._updateSpendMeter();
        }

        _updateSpendMeter() {
            var sEl = document.getElementById('repairSpendInput');
            if (!sEl) return;
            var spend = parseInt(sEl.value, 10) || 0;
            var allocEl = document.getElementById('spendDisplay');
            if (allocEl) allocEl.textContent = '€' + spend.toLocaleString() + 'k';
            var bar = document.getElementById('spendMeterBar');
            if (bar) {
                // Meter scaled against the prudent affordability band (~40% of EBIT).
                var prudent = this.EBIT_CAP_K * 0.4;
                var pct = Math.min(100, Math.round((spend / prudent) * 100));
                bar.style.width = pct + '%';
                if (spend > prudent) {
                    bar.classList.add('lusitania-over');
                } else {
                    bar.classList.remove('lusitania-over');
                }
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('trustDisplay', 'domainState.trustIndex');
            uiManager.bind('adoptionDisplay', 'domainState.adoption', function(v) { return (v || 0) + '%'; });
            uiManager.bind('ethicsDisplay', 'domainState.ethicality');
            uiManager.bind('riskDisplay', 'domainState.turnoverRisk');
            uiManager.bind('strikeDisplay', 'domainState.strikeRisk', function(v) {
                var t = window.mySimulation.t.bind(window.mySimulation);
                if (v >= 55) return t('strike_high');
                if (v >= 30) return t('strike_med');
                return t('strike_low');
            });
            uiManager.bind('financialDisplay', 'domainState.financialImpact', function(v) {
                var n = Math.round((v || 0) * 10) / 10;
                return (n >= 0 ? '€+' : '€') + n + 'M';
            });
            uiManager.bind('deadlineDisplay', 'currentPeriod', function(v) {
                var months = [7, 5, 2, 0];
                return months[Math.min(v - 1, 3)];
            });

            var self = this;
            var spendEl = document.getElementById('repairSpendInput');
            if (spendEl) {
                spendEl.addEventListener('input', function() { self._updateSpendMeter(); });
            }
            this._updateSpendMeter();
        }

        getChartConfig() {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            return {
                trustChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: t('chart_ds_trust'), data: [], borderColor: '#e0a82e', backgroundColor: 'rgba(224,168,46,0.12)', borderWidth: 3, fill: false, tension: 0.3 },
                            { label: t('chart_ds_adoption'), data: [], borderColor: '#3a9d8f', backgroundColor: 'rgba(58,157,143,0.12)', borderWidth: 3, fill: false, tension: 0.3 },
                            { label: t('chart_ds_ethics'), data: [], borderColor: '#6c8cc7', backgroundColor: 'rgba(108,140,199,0.12)', borderWidth: 3, fill: false, tension: 0.3 },
                            { label: t('chart_ds_risk'), data: [], borderColor: '#d9645a', backgroundColor: 'rgba(217,100,90,0.12)', borderWidth: 3, fill: false, tension: 0.3, borderDash: [6, 4] }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_trust_title'), color: '#e8eef5' },
                            legend: { position: 'bottom', labels: { color: '#c4cedb' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: t('chart_axis_index'), color: '#c4cedb' }, ticks: { color: '#9fb0c3' }, grid: { color: 'rgba(159,176,195,0.12)' } },
                            x: { ticks: { color: '#9fb0c3' }, grid: { color: 'rgba(159,176,195,0.08)' } }
                        }
                    }
                },
                positionChart: {
                    type: 'bar',
                    data: {
                        labels: [t('chart_bar_trust'), t('chart_bar_adoption'), t('chart_bar_ethics'), t('chart_bar_risk')],
                        datasets: [
                            { label: t('chart_ds_current'), data: [], backgroundColor: 'rgba(224,168,46,0.7)', borderColor: '#e0a82e', borderWidth: 1 },
                            { label: t('chart_ds_threshold'), data: [], backgroundColor: 'rgba(58,157,143,0.55)', borderColor: '#3a9d8f', borderWidth: 1 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_position_title'), color: '#e8eef5' },
                            legend: { position: 'bottom', labels: { color: '#c4cedb' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: t('chart_axis_score'), color: '#c4cedb' }, ticks: { color: '#9fb0c3' }, grid: { color: 'rgba(159,176,195,0.12)' } },
                            x: { ticks: { color: '#9fb0c3' }, grid: { color: 'rgba(159,176,195,0.08)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            var ds = state.domainState;
            var labels = ds.trustHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                trustChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.trustHistory },
                        { data: ds.adoptionHistory },
                        { data: ds.ethicsHistory },
                        { data: ds.riskHistory }
                    ]
                },
                positionChart: {
                    labels: [t('chart_bar_trust'), t('chart_bar_adoption'), t('chart_bar_ethics'), t('chart_bar_risk')],
                    datasets: [
                        { data: [ds.trustIndex, ds.adoption, ds.ethicality, ds.turnoverRisk] },
                        { data: [55, 70, 55, 45] }
                    ]
                }
            };
        }

        // Composite 0-100 for the reporting/grading layer (results_utils.php reads
        // domainState.performance.overallScore). Same math as getPerformanceSummary's totalScore:
        // trust .35, adoption .25, ethicality .20, low-turnover .20, +/-6 for landed/detonated.
        _composite(x) {
            var trust = x.trustIndex || 0, adoption = x.adoption || 0, ethics = x.ethicality || 0, risk = x.turnoverRisk || 0;
            var riskScore = 100 - risk;
            var s = Math.round(trust * 0.35 + adoption * 0.25 + ethics * 0.20 + riskScore * 0.20);
            if (x.outcome === 'landed') s = Math.min(100, s + 6);
            if (x.outcome === 'detonated') s = Math.max(0, s - 6);
            return Math.max(0, Math.min(100, s));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var trust = r.trustIndex || 0;
            var adoption = r.adoption || 0;
            var ethics = r.ethicality || 0;
            var risk = r.turnoverRisk || 0;
            var fin = r.financialImpact || 0;

            // Composite: trust recovered (35%), adoption (25%), ethicality (20%),
            // and low turnover risk (20%, inverted so low risk scores high).
            var riskScore = 100 - risk;
            var totalScore = Math.round(
                trust * 0.35 + adoption * 0.25 + ethics * 0.20 + riskScore * 0.20
            );
            if (r.outcome === 'landed') totalScore = Math.min(100, totalScore + 6);
            if (r.outcome === 'detonated') totalScore = Math.max(0, totalScore - 6);
            totalScore = Math.max(0, Math.min(100, totalScore));

            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){return window.mySimulation.t(k);} : function(k){return k;};
            var performanceKey = 'grade_demolisher';
            if (totalScore >= 78 && r.outcome === 'landed') performanceKey = 'grade_leader';
            else if (totalScore >= 62) performanceKey = 'grade_manager';
            else if (totalScore >= 45) performanceKey = 'grade_developing';

            var performance = T(performanceKey);
            var insights = [];

            var diagnosedEver = history.some(function(h) { return h.results && h.results.diagnosedRight; });
            if (diagnosedEver) insights.push(T('ins_1'));
            else insights.push(T('ins_2'));

            if (r.profitShareNamed) insights.push(T('ins_3'));
            else insights.push(T('ins_4'));

            if (r.overPromised) insights.push(T('ins_5'));
            else insights.push(T('ins_6'));

            if (r.repair === 'words_only' || r.repairSpent === 0) insights.push(T('ins_7'));
            else insights.push(T('ins_8'));

            if (r.strikeRisk >= 55) insights.push(T('ins_9'));
            else insights.push(T('ins_10'));

            if (r.outcome === 'landed') insights.push(T('ins_11'));
            else insights.push(T('ins_12'));

            return {
                totalScore: totalScore,
                trustIndex: trust,
                adoption: adoption,
                ethicality: ethics,
                turnoverRisk: risk,
                financialImpact: fin,
                strikeRisk: r.strikeRisk,
                outcome: r.outcome,
                overallScore: totalScore,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.overallScore === 'number' ? s.overallScore : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var landed = s.outcome === 'landed';
            var badge = landed
                ? '<span class="et-cm-badge et-cm-yes">' + T('cm_landed') + '</span>'
                : '<span class="et-cm-badge et-cm-no">' + T('cm_detonated') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="et-cm-metric"><span class="et-cm-mv">' + Math.round(s.trustIndex||0) + '</span><span class="et-cm-ml">' + T('cm_m_trust') + '</span></div>'
                + '<div class="et-cm-metric"><span class="et-cm-mv">' + Math.round(s.adoption||0) + '%</span><span class="et-cm-ml">' + T('cm_m_adoption') + '</span></div>'
                + '<div class="et-cm-metric"><span class="et-cm-mv">' + Math.round(s.ethicality||0) + '</span><span class="et-cm-ml">' + T('cm_m_ethics') + '</span></div>'
                + '<div class="et-cm-metric"><span class="et-cm-mv">' + Math.round(s.turnoverRisk||0) + '</span><span class="et-cm-ml">' + T('cm_m_turnover') + '</span></div>';
            return ''
                + '<div class="et-completion">'
                +   '<div class="et-cm-head">'
                +     '<div class="et-cm-score">' + score + '<span class="et-cm-score-max">/100</span></div>'
                +     '<div class="et-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="et-cm-metrics">' + metrics + '</div>'
                +   '<div class="et-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="et-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.outcome === 'landed') return window.mySimulation.t('hint_landed');
            if (results.outcome === 'detonated' && state.currentPeriod >= 4) return window.mySimulation.t('hint_detonated');
            if (!results.diagnosedRight) return window.mySimulation.t('hint_diagnosis');
            if (!results.profitShareNamed) return window.mySimulation.t('hint_profitshare');
            if (results.overPromised) return window.mySimulation.t('hint_overpromise');
            if ((results.repair === 'words_only' || results.repairSpent === 0) && state.currentPeriod >= 3) return window.mySimulation.t('hint_words');
            if (results.strikeRisk >= 55) return window.mySimulation.t('hint_strike');
            if (results.trustIndex < 55) return window.mySimulation.t('hint_lowtrust');
            return window.mySimulation.t('hint_good_progress');
        }

