            return [
                { key: 'results.component', label: 'Diagnosis', i18nKey: 'col_component', formatter: function(v) {
                    var t = window.mySimulation.t.bind(window.mySimulation);
                    var map = { ability: 'comp_short_ability', benevolence: 'comp_short_benevolence', integrity: 'comp_short_integrity' };
                    return map[v] ? t(map[v]) : v;
