                    var t = window.mySimulation.t.bind(window.mySimulation);
                    var map = { full_transparency: 'frame_short_transparency', gains_first: 'frame_short_gains', co_created: 'frame_short_cocreated' };
                    return map[v] ? t(map[v]) : v;
                } },
                { key: 'results.repair', label: 'Repair', i18nKey: 'col_repair', formatter: function(v) {
                    var t = window.mySimulation.t.bind(window.mySimulation);
                    var map = { binding_guarantee: 'repair_short_guarantee', leaders_absorb: 'repair_short_absorb', oversight_council: 'repair_short_council', scaled_profitshare: 'repair_short_profitshare', words_only: 'repair_short_words' };
                    return map[v] ? t(map[v]) : v;
                } },
                { key: 'results.trustIndex', label: 'Trust', i18nKey: 'col_trust' },
                { key: 'results.adoption', label: 'Adoption', i18nKey: 'col_adoption', formatter: function(v) { return (v || 0) + '%'; } },
